test('removeLine rejects when removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine does not mutate input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const inputLinesCopy = JSON.parse(JSON.stringify(r1.value.lines));
  removeLine(r1.value, 'DES-HOUR');
  assert.deepEqual(r1.value.lines, inputLinesCopy);
});

test('addLine and removeLine work together', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  const r3 = addLine(r2.value, { sku: 'COPY-HOUR', qty: 2 });
  const r4 = removeLine(r3.value, 'DES-HOUR');
  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.equal(r4.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r4.value.lines[1].sku, 'COPY-HOUR');
